export const matchWorldCountry = (suffix: string): RegionalEntry | undefined => {
  if (!suffix) return undefined;
  const clean = suffix.trim().toLowerCase();
  const digits = clean.replace(/\D/g, '');

  // 1. Direct match by 2-letter ISO suffix or exact country name
  const exact = WORLD_COUNTRIES.find(
    (c) => c.suffix.toLowerCase() === clean || c.country.toLowerCase() === clean
  );
  if (exact) return exact;

  // 2. Direct match by phone code or code digits
  const codeMatch = WORLD_COUNTRIES.find(
    (c) => c.phoneCode.toLowerCase() === clean || c.codeDigits === clean || `+${c.codeDigits}` === clean
  );
  if (codeMatch) return codeMatch;

  // 3. Digit prefix match sorted by longest dialing code
  if (digits.length > 0) {
    const sorted = [...WORLD_COUNTRIES].sort((a, b) => b.codeDigits.length - a.codeDigits.length);
    const prefixMatch = sorted.find((c) => digits === c.codeDigits || digits.startsWith(c.codeDigits));
    if (prefixMatch) return prefixMatch;
  }

  // 4. Country name start-with match
  if (clean.length >= 3) {
    const startsMatch = WORLD_COUNTRIES.find((c) => c.country.toLowerCase().startsWith(clean));
    if (startsMatch) return startsMatch;
  }

  return undefined;
};

