function encodePostContentForBackend(post: PostItem, fallbackAuthorId?: string): string {
  const cleanText = (post.content || '').replace(/\n?<!--CHX_META:[\s\S]*?-->/g, '').trim();
  const likedList = Array.isArray(post.likedByNodeIds)
    ? Array.from(new Set(post.likedByNodeIds.map((x) => String(x || '').trim().toUpperCase()).filter(Boolean)))
    : [];
  const metaPayload = {
    clientId: post.clientId || post.id,
    createdAt: post.createdAt || Date.now(),
    author: post.author,
    authorId: (post.authorId || fallbackAuthorId || '').trim().toUpperCase() || undefined,
    badge: post.badge || '',
    avatar: post.avatar && post.avatar.length < 4500 ? post.avatar : undefined,
    verifications: Math.max(likedList.length, Number(post.verifications) || 0),
    likedByNodeIds: likedList.length > 0 ? likedList : undefined,
    comments: Array.isArray(post.comments) && post.comments.length > 0 ? post.comments.slice(-20) : undefined,
    resharedPost: post.resharedPost
      ? {
          ...post.resharedPost,
          avatar:
            post.resharedPost.avatar && post.resharedPost.avatar.length < 4500
              ? post.resharedPost.avatar
              : undefined,
          postMedia: undefined
        }
      : undefined
  };
  return `${cleanText || 'Shared post'}\n<!--CHX_META:${JSON.stringify(metaPayload)}-->`;
}

function normalizePostWithReshare(post: PostItem): PostItem {
  let text = post.content || '';
  let extractedReshare: ResharedPostData | undefined = post.resharedPost;
  let extractedCreatedAt = post.createdAt;
  let extractedClientId = post.clientId;
  let extractedAuthor = post.author;
  let extractedAuthorId = post.authorId ? post.authorId.trim().toUpperCase() : undefined;
  let extractedBadge = post.badge === 'CHIXUS Hardware & Grid Operator' ? '' : (post.badge || '');
  let extractedAvatar = post.avatar;
  let extractedLikedBy: string[] = Array.isArray(post.likedByNodeIds)
    ? post.likedByNodeIds.map((x) => String(x || '').trim().toUpperCase()).filter(Boolean)
    : [];
  let extractedVerifications = Number(post.verifications) || 0;
  let extractedComments: string[] = Array.isArray(post.comments) ? [...post.comments] : [];

  const metaMatch = text.match(/\n?<!--CHX_META:([\s\S]*?)-->/);
  if (metaMatch) {
    text = text.replace(/\n?<!--CHX_META:[\s\S]*?-->/g, '').trim();
    if (text === 'Shared post' && extractedReshare) {
      text = '';
    }
    try {
      const parsedMeta = JSON.parse(metaMatch[1]);
      if (parsedMeta.clientId && !extractedClientId) extractedClientId = String(parsedMeta.clientId);
      if (parsedMeta.createdAt && !extractedCreatedAt) extractedCreatedAt = parsedMeta.createdAt;
      const metaAuthorId = typeof parsedMeta.authorId === 'string' ? parsedMeta.authorId.trim().toUpperCase() : '';
      const authorIdWasCorrupted = Boolean(metaAuthorId && extractedAuthorId && metaAuthorId !== extractedAuthorId);
      if (metaAuthorId) {
        extractedAuthorId = metaAuthorId;
      }
      if (
        parsedMeta.author &&
        (authorIdWasCorrupted ||
          !extractedAuthor ||
          /^CHI-[A-Z0-9]{4}-[A-Z]{2,3}$/i.test(extractedAuthor.trim()))
      ) {
        extractedAuthor = parsedMeta.author;
      }
      if (typeof parsedMeta.badge === 'string' && (authorIdWasCorrupted || !extractedBadge)) {
        extractedBadge = parsedMeta.badge === 'CHIXUS Hardware & Grid Operator' ? '' : parsedMeta.badge;
      }
      if (
        parsedMeta.avatar &&
        (authorIdWasCorrupted || !extractedAvatar || extractedAvatar.includes('dicebear'))
      ) {
        extractedAvatar = parsedMeta.avatar;
      }
      if (Array.isArray(parsedMeta.likedByNodeIds)) {
        for (const id of parsedMeta.likedByNodeIds) {
          const clean = String(id || '').trim().toUpperCase();
          if (clean && !extractedLikedBy.includes(clean)) {
            extractedLikedBy.push(clean);
          }
        }
      }
      if (typeof parsedMeta.verifications === 'number' && parsedMeta.verifications > extractedVerifications) {
        extractedVerifications = parsedMeta.verifications;
      }
      if (Array.isArray(parsedMeta.comments)) {
        for (const c of parsedMeta.comments) {
          const cleanC = String(c || '').trim();
          if (cleanC && !extractedComments.includes(cleanC)) {
            extractedComments.push(cleanC);
          }
        }
      }
      if (parsedMeta.resharedPost && !extractedReshare) {
        extractedReshare = {
          ...parsedMeta.resharedPost,
          postMedia: parsedMeta.resharedPost.postMedia || post.postMedia
        };
      }
    } catch {}
  }

  // Ensure legacy posts with verifications > 0 have their likes preserved in likedByNodeIds so another account liking increments (1 -> 2) instead of resetting to 0
  if (extractedLikedBy.length === 0 && extractedVerifications > 0) {
    const seedOwnerId = (extractedAuthorId || 'CHI-7649-NG').trim().toUpperCase();
    extractedLikedBy.push(seedOwnerId);
  }
  while (extractedLikedBy.length < extractedVerifications) {
    const fillerId = `VERIFIED-OP-${extractedLikedBy.length + 1}`;
    if (!extractedLikedBy.includes(fillerId)) {
      extractedLikedBy.push(fillerId);
    } else {
      break;
    }
  }
  extractedLikedBy = Array.from(new Set(extractedLikedBy));
  extractedVerifications = Math.max(extractedLikedBy.length, extractedVerifications);

  // Also upgrade any legacy "🔁 Shared from Author:\n\"...\"" text format into a tamper-proof embedded card
  const legacyRegex = /(?:^|\n\n)🔁 Shared from ([^\n:]+):\s*\n"([\s\S]*)"$/;
  const legacyMatch = text.match(legacyRegex);
  if (legacyMatch) {
    const outerNote = text.slice(0, legacyMatch.index || 0).trim();
    let innerAuthor = legacyMatch[1].trim();
    let innerText = legacyMatch[2].trim();

    // If it was double-nested legacy text, unwrap to the deepest original author & text
    const nestedMatch = innerText.match(/(?:^|\n\n)🔁 Shared from ([^\n:]+):\s*\n"([\s\S]*)"$/);
    if (nestedMatch) {
      innerAuthor = nestedMatch[1].trim();
      innerText = nestedMatch[2].replace(/"+$/, '').trim();
    }

    text = outerNote;
    if (!extractedReshare) {
      extractedReshare = {
        id: `orig-${post.id}`,
        author: innerAuthor,
        badge: '',
        avatar: post.avatar || defaultBlankOperatorAvatar,
        time: post.time || 'Just now',
        createdAt: extractedCreatedAt,
        content: innerText,
        postMedia: post.postMedia
      };
    }
  }

  if (text === 'Shared post' && extractedReshare) {
    text = '';
  }

  return {
    ...post,
    clientId: extractedClientId,
    author: extractedAuthor,
    authorId: extractedAuthorId,
    badge: extractedBadge,
    avatar: extractedAvatar,
    createdAt: extractedCreatedAt,
    content: text,
    verifications: extractedVerifications,
    likedByNodeIds: extractedLikedBy,
    comments: extractedComments,
    postMedia: extractedReshare ? undefined : post.postMedia,
    resharedPost: extractedReshare
      ? {
          ...extractedReshare,
          badge: extractedReshare.badge === 'CHIXUS Hardware & Grid Operator' ? '' : (extractedReshare.badge || ''),
          postMedia: extractedReshare.postMedia || post.postMedia
        }
      : undefined
  };
}

function compressImageDataUrl(dataUrl: string, maxDim = 420, quality = 0.72): Promise<string> {
  return new Promise((resolve) => {
    if (!dataUrl || !dataUrl.startsWith('data:image')) {
      resolve(dataUrl);
      return;
    }
    const img = new Image();
    img.onload = () => {
      try {
        const w = img.naturalWidth || img.width || 300;
        const h = img.naturalHeight || img.height || 300;
        const scale = Math.min(1, maxDim / Math.max(w, h));
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(w * scale));
        canvas.height = Math.max(1, Math.round(h * scale));
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          resolve(dataUrl);
          return;
        }
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        const compressed = canvas.toDataURL('image/jpeg', quality);
        resolve(compressed.length < dataUrl.length ? compressed : dataUrl);
      } catch {
        resolve(dataUrl);
      }
    };
    img.onerror = () => resolve(dataUrl);
    img.src = dataUrl;
  });
}

function shrinkOversizedBase64InValue(key: string, rawValue: string): string {
  if (!rawValue || rawValue.length < 65000) return rawValue;
  // Never trim, truncate, or strip attachments from chat messages - all user messages and attachments must be preserved permanently
  if (key.includes('messages') || key.includes('chat')) return rawValue;
  try {
    const parsed = JSON.parse(rawValue);
    const savedCurrentAv = localStorage.getItem('chixus_avatar_v7') || defaultBlankOperatorAvatar;
    if (Array.isArray(parsed)) {
      const limit = key.includes('posts') ? 25 : 15;
      const trimmed = parsed.slice(0, limit).map((item: any) => {
        if (!item || typeof item !== 'object') return item;
        const copy = { ...item };
        if (typeof copy.avatar === 'string' && copy.avatar.startsWith('data:') && copy.avatar.length > 90000) {
          copy.avatar = savedCurrentAv;
        }
        if (typeof copy.avatarUrl === 'string' && copy.avatarUrl.startsWith('data:') && copy.avatarUrl.length > 90000) {
          const itemId = String(copy.secretId || copy.frontendId || copy.backendId || '').trim().toUpperCase();
          if (itemId) {
            localforage.setItem(`chixus_idb_avatar_${itemId}`, copy.avatarUrl).catch(() => {});
          }
          copy.avatarUrl = savedCurrentAv;
        }
        if (typeof copy.coverUrl === 'string' && copy.coverUrl.startsWith('data:') && copy.coverUrl.length > 65000) {
          const itemId = String(copy.secretId || copy.frontendId || copy.backendId || '').trim().toUpperCase();
          if (itemId) {
            localforage.setItem(`chixus_idb_cover_${itemId}`, copy.coverUrl).catch(() => {});
          }
          delete copy.coverUrl;
        }
        if (typeof copy.postMedia === 'string' && copy.postMedia.startsWith('data:') && copy.postMedia.length > 75000) {
          delete copy.postMedia;
        }
        if (typeof copy.imageAttachment === 'string' && copy.imageAttachment.startsWith('data:') && copy.imageAttachment.length > 65000) {
          delete copy.imageAttachment;
        }
        if (typeof copy.image === 'string' && copy.image.startsWith('data:') && copy.image.length > 55000) {
          copy.image = 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&q=80&w=400';
        }
        return copy;
      });
      return JSON.stringify(trimmed);
    }
    if (parsed && typeof parsed === 'object') {
      const copy: any = { ...parsed };
      const secId = String(copy.secretId || '').trim().toUpperCase();
      if (typeof copy.avatarUrl === 'string' && copy.avatarUrl.startsWith('data:') && copy.avatarUrl.length > 90000) {
        if (secId) {
          localforage.setItem(`chixus_idb_avatar_${secId}`, copy.avatarUrl).catch(() => {});
        }
        copy.avatarUrl = savedCurrentAv;
      }
      if (typeof copy.coverUrl === 'string' && copy.coverUrl.startsWith('data:') && copy.coverUrl.length > 75000) {
        if (secId) {
          localforage.setItem(`chixus_idb_cover_${secId}`, copy.coverUrl).catch(() => {});
        }
        delete copy.coverUrl;
      }
      return JSON.stringify(copy);
    }
  } catch {}
  return rawValue;
}

function reclaimLocalStorageSpace(): void {
  try {
    localStorage.removeItem('chixus_scan_logs_v8');
    const heavyKeys = [
      'chixus_fraud_proof_ledger_v9',
      'chixus_feed_posts_v7',
      'chixus_registered_users',
      'chixus_peer_profiles_v7',
      'chixus_current_user_profile'
    ];
    for (const k of heavyKeys) {
      const val = localStorage.getItem(k);
      if (val && val.length > 45000) {
        const compacted = shrinkOversizedBase64InValue(k, val);
        try {
          localStorage.setItem(k, compacted);
        } catch {
          if (k === 'chixus_fraud_proof_ledger_v9') {
            localStorage.removeItem(k);
          }
        }
      }
    }
    const activeId = (localStorage.getItem('chixus_generated_secret_id') || '').trim().toUpperCase();
    const av = localStorage.getItem('chixus_avatar_v7');
    if (av && av.startsWith('data:') && av.length > 50000) {
      if (activeId) {
        localforage.setItem(`chixus_idb_avatar_${activeId}`, av).catch(() => {});
      }
      localStorage.removeItem('chixus_avatar_v7');
    }
    const cov = localStorage.getItem('chixus_cover_v7');
    if (cov && cov.startsWith('data:') && cov.length > 50000) {
      if (activeId) {
        localforage.setItem(`chixus_idb_cover_${activeId}`, cov).catch(() => {});
      }
      localStorage.removeItem('chixus_cover_v7');
    }
  } catch {}
}

function safeSetLocalStorage(key: string, value: string): void {
  try {
    const prepared = value.length > 90000 ? shrinkOversizedBase64InValue(key, value) : value;
    localStorage.setItem(key, prepared);
  } catch {
    reclaimLocalStorageSpace();
    try {
      const compacted = shrinkOversizedBase64InValue(key, value);
      localStorage.setItem(key, compacted);
    } catch {
      localforage.setItem(key, value).catch(() => {});
    }
  }
}

function safeSaveUserProfileToStorage(profile: any): void {
  if (!profile) return;
  try {
    const secId = String(profile.secretId || '').trim().toUpperCase();
    if (profile.avatarUrl && profile.avatarUrl.startsWith('data:') && profile.avatarUrl !== defaultBlankOperatorAvatar) {
      if (secId) {
        localforage.setItem(`chixus_idb_avatar_${secId}`, profile.avatarUrl).catch(() => {});
      }
    }
    if (profile.coverUrl && profile.coverUrl.startsWith('data:') && profile.coverUrl !== metallicBanner) {
      if (secId) {
        localforage.setItem(`chixus_idb_cover_${secId}`, profile.coverUrl).catch(() => {});
      }
    }
    if (secId) {
      localforage.setItem(`chixus_profile_${secId}`, profile).catch(() => {});
    }
    localforage.setItem('chixus_current_user_profile', profile).catch(() => {});
    safeSetLocalStorage('chixus_current_user_profile', JSON.stringify(profile));
  } catch {}
}

function safeSaveScanLogsToLocalStorage(logs: ScanLog[]): void {
  try {
    const compactLogs = logs.slice(0, 6).map((item) => ({
      ...item,
      image:
        item.image && item.image.startsWith('data:') && item.image.length > 35000
          ? 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&q=80&w=400'
          : item.image
    }));
    const serialized = JSON.stringify(compactLogs);
    safeSetLocalStorage('chixus_fraud_proof_ledger_v9', serialized);
  } catch {}
}

