  const [aiVerifyBadgeSrc, setAiVerifyBadgeSrc] = useState<string>(chixusAiVerifiedBadge);

  useEffect(() => {
    const processEmblemToTransparentPng = (src: string, onDone: (dataUrl: string) => void) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        try {
          const size = 256;
          const canvas = document.createElement('canvas');
          canvas.width = size;
          canvas.height = size;
          const ctx = canvas.getContext('2d');
          if (!ctx) return;
          ctx.drawImage(img, 0, 0, size, size);
          const imageData = ctx.getImageData(0, 0, size, size);
          const data = imageData.data;
          const visited = new Uint8Array(size * size);
          const queue = new Int32Array(size * size);
          let head = 0;
          let tail = 0;

          const tryEnqueue = (x: number, y: number) => {
            if (x < 0 || x >= size || y < 0 || y >= size) return;
            const idx = y * size + x;
            if (visited[idx]) return;
            const p = idx * 4;
            const r = data[p];
            const g = data[p + 1];
            const b = data[p + 2];
            // Only strip pure black outer background corners (< 16) so dark metallic gear teeth and CHIXUS banner remain 100% intact
            if (r < 16 && g < 16 && b < 16) {
              visited[idx] = 1;
              queue[tail++] = idx;
            }
          };

          for (let i = 0; i < size; i++) {
            tryEnqueue(i, 0);
            tryEnqueue(i, size - 1);
            tryEnqueue(0, i);
            tryEnqueue(size - 1, i);
          }

          while (head < tail) {
            const curr = queue[head++];
            data[curr * 4 + 3] = 0;
            const cx = curr % size;
            const cy = (curr / size) | 0;
            tryEnqueue(cx + 1, cy);
            tryEnqueue(cx - 1, cy);
            tryEnqueue(cx, cy + 1);
            tryEnqueue(cx, cy - 1);
          }

          let minX = size;
          let minY = size;
          let maxX = 0;
          let maxY = 0;
          for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
              const p = (y * size + x) * 4;
              if (data[p + 3] > 0) {
                if (x < minX) minX = x;
                if (x > maxX) maxX = x;
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
              }
            }
          }

          ctx.putImageData(imageData, 0, 0);
          if (maxX > minX && maxY > minY) {
            const pad = 2;
            const sx = Math.max(0, minX - pad);
            const sy = Math.max(0, minY - pad);
            const sw = Math.min(size - sx, maxX - minX + 1 + pad * 2);
            const sh = Math.min(size - sy, maxY - minY + 1 + pad * 2);
            const side = Math.max(sw, sh);
            const out = document.createElement('canvas');
            out.width = side;
            out.height = side;
            const outCtx = out.getContext('2d');
            if (outCtx) {
              outCtx.drawImage(
                canvas,
                sx,
                sy,
                sw,
                sh,
                (side - sw) / 2,
                (side - sh) / 2,
                sw,
                sh
              );
              onDone(out.toDataURL('image/png'));
              return;
            }
          }
          onDone(canvas.toDataURL('image/png'));
        } catch {
          onDone(src);
        }
      };
      img.onerror = () => onDone(src);
      img.src = src;
    };

    processEmblemToTransparentPng(chixusAiVerifiedBadge, (dataUrl) => {
      setAiVerifyBadgeSrc(dataUrl || chixusAiVerifiedBadge);
    });
  }, []);

  // Profile Edit Temp State
